contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // The test takes a target caller address simulated by sending calls from this contract
    // and an amount to attempt to withdraw from c. We require this contract to hold
    // enough Ether if it will send value to c (not needed here), so no balance precondition.
    function run(address someRecipient, uint amount) public payable {
        require(someRecipient != address(0));

        // Ensure we observe initial public values
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // Attempt withdraw as non-owner: since this InvMutTest contract deployed c,
        // it is the owner. To simulate a non-owner call we must use c.sendMoney to
        // make c call a fallback on some other contract — but we cannot change msg.sender
        // of calls to c. Instead, we check the invariant that only owner can successfully
        // decrease c's balance via withdraw/withdrawAll by trying withdraw and treating
        // its success or revert accordingly. We perform a withdraw attempt and catch revert.

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: if withdraw reverted then contract balance and depositsCount must be unchanged;
        // if it did not revert then the contract balance must be <= beforeBalance and depositsCount may change only via fallback (not by withdraw), so depositsCount must be unchanged by withdraw.
        assert(
            (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
            ||
            (!reverted && afterDeposits == beforeDeposits && afterBalance <= beforeBalance)
        );
    }

    // receive to accept any Ether forwarded to this test contract
    receive() external payable {}
}

