pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address someRecipient, uint256 amount) internal {
        vm.assume(someRecipient != address(0));
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue((reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
            ||
            (!reverted && afterDeposits == beforeDeposits && afterBalance <= beforeBalance));
    }

    function testFuzz_run(address someRecipient, uint256 amount) public {
        vm.assume(someRecipient.code.length == 0 && uint160(someRecipient) > 0xffff && someRecipient != address(this) && someRecipient != address(c) && someRecipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && someRecipient != 0x000000000000000000636F6e736F6c652e6c6f67 && someRecipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && someRecipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(someRecipient, amount);
    }

    receive() external payable {}
}
